package com.snoworca.naruserve;
import static org.junit.Assert.assertEquals;
import com.snoworca.naruserve.common.AbortListeners;
import com.snoworca.naruserve.internal.DefaultResponse;
import com.snoworca.naruserve.internal.DefaultRestApp;
import com.snoworca.naruserve.spi.HttpExchange;
import com.snoworca.naruserve.testing.RecordingExchange;
import com.snoworca.naruserve.testing.RecordingLogger;
import java.io.IOException;
import java.lang.reflect.InvocationTargetException;
import java.lang.reflect.Proxy;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.concurrent.atomic.AtomicReference;
import org.junit.Test;
public class ZzProofFnd101Test {
  @Test public void adapterAbortDuringAnOpenSessionAfter101() {
    RecordingExchange rec = new RecordingExchange("GET", "/ws", "Connection", "Upgrade", "Upgrade", "websocket");
    AbortListeners aborts = new AbortListeners();
    rec.webSocketScript = (settings, endpoint) -> {
      WebSocketDispatchTest.PeerChannel ch = new WebSocketDispatchTest.PeerChannel();
      ch.open = true;
      endpoint.onOpen(ch);            // 101 written, session open
      aborts.abort();                 // adapter stop() aborts the exchange mid-session
      rec.finishFailure = new IOException("aborted");
      ch.open = false;
      endpoint.onClose(1006, "");
    };
    HttpExchange ex = (HttpExchange) Proxy.newProxyInstance(HttpExchange.class.getClassLoader(), new Class<?>[] {HttpExchange.class}, (proxy, m, args) -> {
      if (m.getName().equals("onAbort")) { aborts.onAbort((Runnable) args[0]); return null; }
      try { return m.invoke(rec, args); } catch (InvocationTargetException e) { throw e.getCause(); }
    });
    RecordingLogger log = new RecordingLogger();
    DefaultRestApp app = new DefaultRestApp();
    app.logger(log);
    AtomicInteger listener = new AtomicInteger();
    AtomicReference<Response> captured = new AtomicReference<>();
    app.use((req, res, next) -> { captured.set(res); res.onAbort(listener::incrementAndGet); next.run(); });
    app.ws("/ws", (req, ws) -> { });
    app.freeze();
    app.dispatcher().handle(ex);
    System.out.println("PROOF state=" + ((DefaultResponse) captured.get()).state() + " listener=" + listener.get() + " exAborts=" + rec.aborts.get() + " info=" + log.info());
    assertEquals(log.info().toString(), 1, RecordingLogger.countMatching(log.info(), "GET /ws .*"));
  }
}
